export type StandardRule = {
  id: string;
  title: string;
  category: string;
  explanation: string;
  applicability: string;
  severityGuidance: string;
  evidenceRequirements: string;
  remediation: string[];
  verification: string[];
  references: string[];
};

const rule = (
  id: string,
  title: string,
  category: string,
  explanation: string,
  applicability: string,
  severityGuidance: string,
  remediation: string[],
  verification: string[],
  references: string[] = [],
): StandardRule => ({
  id,
  title,
  category,
  explanation,
  applicability,
  severityGuidance,
  evidenceRequirements:
    "Cite a repository-relative file and line. Absence of evidence is not proof of a vulnerability.",
  remediation,
  verification,
  references,
});

